<?php
require __DIR__.'/app/bootstrap.php'; require_login(); require __DIR__.'/app/layout.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: 0; $editing=$id>0; $errors=[];
$data=['applicant_no'=>'','first_name'=>'','last_name'=>'','date_of_birth'=>'','sex'=>'','phone'=>'','email'=>'','address'=>'','district'=>'','nationality'=>'Malawian','status'=>'Pending'];
if($editing){$st=$pdo->prepare('SELECT * FROM applicants WHERE id=?');$st->execute([$id]);$row=$st->fetch();if(!$row){flash('error','Applicant not found.');redirect('applicants.php');}$data=array_merge($data,$row);}
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); foreach($data as $key=>$v){ if(isset($_POST[$key])) $data[$key]=trim((string)$_POST[$key]); }
    if($data['first_name']==='')$errors[]='First name is required.'; if($data['last_name']==='')$errors[]='Last name is required.';
    if($data['date_of_birth']==='' || !DateTime::createFromFormat('!Y-m-d',$data['date_of_birth']) || DateTime::createFromFormat('!Y-m-d',$data['date_of_birth'])->format('Y-m-d')!==$data['date_of_birth'])$errors[]='Enter a valid date of birth.';
    if($data['date_of_birth']!=='' && $data['date_of_birth']>date('Y-m-d'))$errors[]='Date of birth cannot be in the future.';
    if(!in_array($data['sex'],['Female','Male','Other'],true))$errors[]='Select a valid sex value.';
    if($data['email']!=='' && !filter_var($data['email'],FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';
    if($data['phone']!=='' && !preg_match('/^[0-9+()\-\s]{7,20}$/',$data['phone']))$errors[]='Enter a valid phone number.';
    if(!in_array($data['status'],['Pending','In Review','Approved','Rejected'],true))$errors[]='Select a valid status.';
    foreach(['first_name'=>100,'last_name'=>100,'phone'=>25,'email'=>150,'address'=>255,'district'=>100,'nationality'=>80] as $k=>$max)if(mb_strlen($data[$k])>$max)$errors[]='The '.$k.' field is too long.';
    if(!$errors){try{
        if($editing){$st=$pdo->prepare('UPDATE applicants SET first_name=?,last_name=?,date_of_birth=?,sex=?,phone=?,email=?,address=?,district=?,nationality=?,status=?,updated_at=NOW() WHERE id=?');$st->execute([$data['first_name'],$data['last_name'],$data['date_of_birth'],$data['sex'],$data['phone']?:null,$data['email']?:null,$data['address']?:null,$data['district']?:null,$data['nationality'],$data['status'],$id]);log_activity($pdo,'UPDATE_APPLICANT',$id,'Updated applicant details');flash('success','Applicant details updated successfully.');redirect('applicant_view.php?id='.$id);
        } else { $no='NRB-'.date('y').'-'.strtoupper(bin2hex(random_bytes(3)));$st=$pdo->prepare('INSERT INTO applicants (applicant_no,first_name,last_name,date_of_birth,sex,phone,email,address,district,nationality,status) VALUES (?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$no,$data['first_name'],$data['last_name'],$data['date_of_birth'],$data['sex'],$data['phone']?:null,$data['email']?:null,$data['address']?:null,$data['district']?:null,$data['nationality'],$data['status']]);$newId=(int)$pdo->lastInsertId();$r=$pdo->prepare('INSERT INTO registrations (applicant_id,registration_date,office_name,notes) VALUES (?,CURDATE(),?,?)');$r->execute([$newId,'Main Registration Office','Created through registration form']);log_activity($pdo,'CREATE_APPLICANT',$newId,'Created fictional applicant record');flash('success','Applicant registered successfully. Applicant number: '.$no);redirect('applicant_view.php?id='.$newId); }
    }catch(PDOException $e){if($e->getCode()==='23000')$errors[]='A duplicate or conflicting value was detected. Check the record and try again.';else{$errors[]='The record could not be saved. Please try again.';error_log($e->getMessage());}}
    }
}
page_header($editing?'Edit applicant':'Register applicant'); ?>
<?php if($errors): ?><div class="alert error"><strong>Please correct the following:</strong><ul><?php foreach(array_unique($errors) as $er): ?><li><?=e($er)?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form class="panel form-panel" method="post" novalidate><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="section-title"><h2>Personal information</h2><p>Fields marked * are required.</p></div><div class="form-grid"><label>First name *<input name="first_name" required maxlength="100" value="<?=e($data['first_name'])?>"></label><label>Last name *<input name="last_name" required maxlength="100" value="<?=e($data['last_name'])?>"></label><label>Date of birth *<input type="date" name="date_of_birth" required max="<?=date('Y-m-d')?>" value="<?=e($data['date_of_birth'])?>"></label><label>Sex *<select name="sex" required><option value="">Select</option><?php foreach(['Female','Male','Other'] as $v): ?><option <?= $data['sex']===$v?'selected':'' ?>><?=e($v)?></option><?php endforeach; ?></select></label><label>Phone number<input name="phone" maxlength="25" value="<?=e($data['phone'])?>" placeholder="e.g. +265 991 000 000"></label><label>Email address<input type="email" name="email" maxlength="150" value="<?=e($data['email'])?>"></label><label>Nationality<input name="nationality" maxlength="80" value="<?=e($data['nationality'])?>"></label><label>District<input name="district" maxlength="100" value="<?=e($data['district'])?>"></label><label class="span-2">Residential address<textarea name="address" rows="3" maxlength="255"><?=e($data['address'])?></textarea></label><?php if($editing): ?><label>Application status<select name="status"><?php foreach(['Pending','In Review','Approved','Rejected'] as $v): ?><option <?= $data['status']===$v?'selected':'' ?>><?=e($v)?></option><?php endforeach; ?></select></label><?php endif; ?></div><div class="form-actions"><a class="btn secondary" href="<?= $editing?'applicant_view.php?id='.$id:'applicants.php' ?>">Cancel</a><button class="btn primary" type="submit"><?= $editing?'Save changes':'Register applicant' ?></button></div></form>
<?php page_footer(); ?>
